const UNALLOCATED_HALALA = 0.005;

/** RF-15: branch BS badge uses API unallocated fields, never recomputes the plug. */
export function pickBsUnallocatedBalance(report, { branchSelected } = {}) {
    const r = report && typeof report === 'object' ? report : {};
    const hasDiffU = r.differenceWithUnallocated != null && r.differenceWithUnallocated !== '';
    const hasBalU = r.isBalancedWithUnallocated != null;
    if (branchSelected && (hasDiffU || hasBalU)) {
        const difference = hasDiffU ? Number(r.differenceWithUnallocated) : 0;
        const isBalanced = hasBalU
            ? Boolean(r.isBalancedWithUnallocated)
            : Number.isFinite(difference) && Math.abs(difference) < UNALLOCATED_HALALA;
        return {
            difference: Number.isFinite(difference) ? difference : 0,
            isBalanced,
            usedUnallocated: true,
        };
    }
    return {
        difference: Number(r.difference || 0),
        isBalanced: Boolean(r.isBalanced),
        usedUnallocated: false,
    };
}

/** RF-15: branch TB badge uses isBalancedWithUnallocated when the API sends it. */
export function pickTbUnallocatedBalance(report, { branchSelected } = {}) {
    const r = report && typeof report === 'object' ? report : {};
    if (branchSelected && r.isBalancedWithUnallocated != null) {
        return { isBalanced: Boolean(r.isBalancedWithUnallocated), usedUnallocated: true };
    }
    return { isBalanced: Boolean(r.isBalanced), usedUnallocated: false };
}

export function reportRowFlags(row) {
    return {
        inactive: row?.isInactive === true,
        shownBecauseBalance: row?.hqShownBecauseBalance === true,
    };
}

export function listMissingBsTbFields(report, { kind, branchSelected } = {}) {
    if (!report || typeof report !== 'object') return [];
    const missing = [];
    if (branchSelected && report.unallocated == null) missing.push('unallocated');
    if (kind === 'bs' && branchSelected && report.differenceWithUnallocated == null) {
        missing.push('differenceWithUnallocated');
    }
    if (kind === 'tb' && branchSelected && report.isBalancedWithUnallocated == null) {
        missing.push('isBalancedWithUnallocated');
    }
    return missing;
}

/** Simple sum of shown leaf Dr/Cr (no heading rollups). */
export function tbLeafDebitCredit(rows) {
    let debitH = 0;
    let creditH = 0;
    for (const row of rows || []) {
        if (row?.isHeading) continue;
        const dr = Number(row.periodDebit ?? row.debitBalance ?? 0);
        const cr = Number(row.periodCredit ?? row.creditBalance ?? 0);
        if (Number.isFinite(dr)) debitH += Math.round(dr * 100);
        if (Number.isFinite(cr)) creditH += Math.round(cr * 100);
    }
    return { debit: debitH / 100, credit: creditH / 100, equal: debitH === creditH };
}
